export type RecordedTime = { timeSec: number; rate: number; upperBoundSec?: number };

export function createDataClock(wallNowSec = () => Date.now() / 1000) {
  let anchor: { time: RecordedTime; receivedWall: number } | null = null;
  return {
    setTime(time: RecordedTime | null) {
      anchor = time ? { time: { ...time }, receivedWall: wallNowSec() } : null;
    },
    nowSec() {
      if (!anchor) return wallNowSec();
      const { time, receivedWall } = anchor;
      if (time.rate === 0) return time.timeSec;
      const now = time.timeSec + Math.max(0, wallNowSec() - receivedWall) * time.rate;
      return time.upperBoundSec === undefined ? now : Math.min(time.upperBoundSec, now);
    }
  };
}

export const defaultDataClock = createDataClock();
let selectedClock: { nowSec(): number } = defaultDataClock;
