struct interface_id {
	std::uint32_t capture_id{0};
	std::string name;
	bool has_capture_id{false};

	bool operator==(const interface_id &o) const noexcept {
		if(has_capture_id && o.has_capture_id) {
			return capture_id == o.capture_id;
		}
		return has_capture_id == o.has_capture_id && name == o.name;
	}
};

struct interface_id_hash {
	std::size_t operator()(const interface_id &v) const noexcept {
		if(v.has_capture_id) {
			return std::hash<std::uint32_t>{}(v.capture_id);
		}
		return std::hash<std::string>{}(v.name);
	}
};

struct counter_value {
	std::uint64_t window{0};
	std::uint64_t total{0};
	bool initialized{false};

	void update(std::uint64_t value) {
		if(initialized) {
			window = (value >= total) ? (value - total) : 0;
		}
		else {
			window = 0;
			initialized = true;
		}
		total = value;
	}
};

struct interface_stats {
	counter_value rx_bytes;
	counter_value tx_bytes;
