void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
